schemas:
{
    "@context":"https://schema.org",
    "@type":"FAQPage",
    "mainEntity":[
      {"@type":"Question","name":"What’s the difference between copywriting and content writing?","acceptedAnswer":{"@type":"Answer","text":"Copywriting drives an action (enquiries, calls, purchases) like landing pages, ads, and email sequences. Content writing builds trust and visibility (blogs, guides, SEO pages) to attract and nurture the right audience. Most brands need both, aligned end-to-end."}},
      {"@type":"Question","name":"How do your SEO content writing services work?","acceptedAnswer":{"@type":"Answer","text":"We start with goals, then do keyword + intent research, competitor gap analysis, and outline approval. After writing, we edit for clarity + on-page SEO (headings, internal linking, meta suggestions). You get publish-ready content."}},
      {"@type":"Question","name":"How long does it take for SEO content to show results?","acceptedAnswer":{"@type":"Answer","text":"SEO compounds. Early movement can happen in weeks, but meaningful traffic and lead lift typically builds over months depending on competition, site authority, and publishing consistency. We track rankings, clicks, and conversions to show progress."}},
      {"@type":"Question","name":"Do you use AI to write content?","acceptedAnswer":{"@type":"Answer","text":"We use AI for research support (topic expansion, comparisons, clustering), not for publishing generic output. Final writing and editing stays human so your content has real structure, clarity, and an on-brand voice."}},
      {"@type":"Question","name":"Who owns the content after delivery?","acceptedAnswer":{"@type":"Answer","text":"You own it. Once the milestone is cleared, the final approved content becomes your IP to publish and repurpose. NDA-friendly execution is available if required."}},
      {"@type":"Question","name":"How do you measure whether the content is working?","acceptedAnswer":{"@type":"Answer","text":"We track organic clicks/impressions, keyword movement, CTR, engagement, conversions (calls/forms/enquiries), and lead quality feedback. If the goal is leads, we optimize the conversion path, not vanity metrics."}}
    ]
  }

