#dgsNav,
#dgsNav *,
#dgsNav *::before,
#dgsNav *::after {
  box-sizing: border-box !important;
  -webkit-font-smoothing: antialiased !important;
}

#dgsNav a,
#dgsNav a:hover,
#dgsNav a:visited,
#dgsNav a:focus,
#dgsNav a:active {
  text-decoration: none !important;
  outline: none !important;
  box-shadow: none !important;
  border: none !important;
}

#dgsNav {
  --acc: #FD5C62;
  --blk: #080808;
  --bdr: rgba(255,255,255,0.08);
  --mut: rgba(255,255,255,0.35);
  --bar: 100px;
}

#dgsBar {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: var(--bar) !important;
  z-index: 99999 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  padding: 0 48px !important;
  background: transparent !important;
  background-image: none !important;
  transition: background-color .4s ease !important;
}

#dgsBar.scrolled,
#dgsNav.nav-open #dgsBar {
  background-color: rgba(8,8,8,.93) !important;
  backdrop-filter: blur(14px) !important;
  -webkit-backdrop-filter: blur(14px) !important;
}

#dgsLogo {
  display: flex !important;
  align-items: center !important;
  height: var(--bar) !important;
  flex-shrink: 0 !important;
  text-decoration: none !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
}

#dgsLogo img {
  height: 117px !important;
  width: 117px !important;
  object-fit: contain !important;
  display: block !important;
}

#dgsRight {
  display: flex !important;
  align-items: center !important;
  gap: 14px !important;
}

#dgsPill {
  display: inline-flex !important;
  align-items: center !important;
  gap: 8px !important;
  font-family: 'DM Sans', sans-serif !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  letter-spacing: .12em !important;
  text-transform: uppercase !important;
  color: #fff !important;
  background-color: #FD5C62 !important;
  background-image: none !important;
  padding: 11px 22px !important;
  border-radius: 100px !important;
  border: none !important;
  box-shadow: none !important;
  white-space: nowrap !important;
  cursor: pointer !important;
  transition: transform .3s ease, box-shadow .3s ease !important;
}

#dgsPill:hover {
  transform: scale(1.04) !important;
  box-shadow: 0 0 22px rgba(253,92,98,.5) !important;
  color: #fff !important;
}

#dgsPill svg {
  width: 13px;
  height: 13px;
  stroke: #fff;
  fill: none;
  stroke-width: 2;
  flex-shrink: 0;
}

#dgsTrig {
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  border: 1px solid rgba(255,255,255,.22) !important;
  border-radius: 100px !important;
  padding: 10px 18px !important;
  cursor: pointer !important;
  box-shadow: none !important;
  outline: none !important;
  user-select: none !important;
  -webkit-user-select: none !important;
  transition: border-color .3s, background-color .3s !important;
}

#dgsTrig:hover {
  background-color: rgba(255,255,255,.06) !important;
  border-color: rgba(255,255,255,.4) !important;
}

#dgsLines {
  display: flex !important;
  flex-direction: column !important;
  gap: 4px !important;
  width: 20px !important;
  pointer-events: none !important;
}

#dgsLines em {
  display: block !important;
  height: 1.5px !important;
  width: 100% !important;
  background-color: #ffffff !important;
  border-radius: 2px !important;
  font-style: normal !important;
  transition: transform .42s cubic-bezier(.76,0,.24,1),
              opacity .42s ease,
              width .42s ease !important;
}

#dgsLines em:nth-child(2) {
  width: 65% !important;
}

#dgsNav.nav-open #dgsLines em:nth-child(1) {
  transform: translateY(5.5px) rotate(45deg) !important;
  width: 100% !important;
}

#dgsNav.nav-open #dgsLines em:nth-child(2) {
  opacity: 0 !important;
  transform: scaleX(0) !important;
}

#dgsNav.nav-open #dgsLines em:nth-child(3) {
  transform: translateY(-5.5px) rotate(-45deg) !important;
}

#dgsTrigLabel {
  font-family: 'DM Sans', sans-serif !important;
  font-size: 11px !important;
  font-weight: 600 !important;
  letter-spacing: .18em !important;
  text-transform: uppercase !important;
  color: #ffffff !important;
  min-width: 38px !important;
  pointer-events: none !important;
  line-height: 1 !important;
}

#dgsOverlay {
  position: fixed !important;
  top: var(--bar) !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  height: calc(100vh - var(--bar)) !important;
  height: calc(100dvh - var(--bar)) !important;
  z-index: 99998 !important;
  visibility: hidden !important;
  pointer-events: none !important;
  overflow: hidden !important;
  max-width: 100vw !important;
  overscroll-behavior: contain !important;
}

#dgsNav.nav-open #dgsOverlay {
  visibility: visible !important;
  pointer-events: auto !important;
}

#dgsPanel {
  position: absolute !important;
  inset: 0 !important;
  height: 100% !important;
