/* ==================== SERVICES REVEAL - OPTIMIZED ==================== */

.services-reveal {
  position: relative;
  min-height: 100vh;
  padding: 120px 0 150px;
  overflow: hidden;
  contain: layout style paint;
}

.services-reveal,
.services-reveal * {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif !important;
}

.services-reveal-container {
  max-width: 1600px;
  margin: 0 auto;
  padding: 0 80px;
  position: relative;
  z-index: 2;
}

/* ==================== HEADER ==================== */

.services-reveal-header {
  margin-bottom: 100px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  padding-bottom: 60px;
  max-width: 900px;
}

.services-reveal-label {
  display: block;
  font-size: 11px;
  font-weight: 200;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.35);
  margin-bottom: 30px;
}

.services-reveal-title {
  font-size: clamp(2.5rem, 5vw, 5rem);
  font-weight: 100;
  line-height: 1.3;
  letter-spacing: -0.04em;
  margin: 0 0 40px 0;
  padding-bottom: 20px;
  overflow: visible;
}

.services-reveal-word {
  display: block;
  background: linear-gradient(90deg, #667eea 0%, #764ba2 25%, #ec4899 50%, #f59e0b 75%, #667eea 100%);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: gradientFlow 8s linear infinite;
  will-change: transform, opacity;
}

@keyframes gradientFlow {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

.services-reveal-intro {
  font-size: clamp(1rem, 1.6vw, 1.3rem);
  font-weight: 100;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.4);
  margin: 0;
  letter-spacing: 0.01em;
  will-change: transform, opacity;
}

/* ==================== SERVICES LIST ==================== */

.services-reveal-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* ==================== SERVICE ITEM - GPU OPTIMIZED ==================== */

.service-reveal-item {
  display: grid;
  grid-template-columns: 80px 1fr;
  gap: 60px;
  padding: 60px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  position: relative;
  will-change: transform, opacity;
  transform: translateZ(0);
  backface-visibility: hidden;
}

.service-reveal-item:last-child {
  border-bottom: none;
}

/* Gradient line - GPU accelerated */
.service-reveal-item::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 1px;
  background: linear-gradient(90deg, #667eea 0%, #ec4899 50%, #f59e0b 100%);
  transition: width 1.2s cubic-bezier(0.4, 0, 0.2, 1);
  will-change: width;
}

.service-reveal-item.active::before {
  width: 100%;
}

.service-reveal-number {
  font-size: 3rem;
  font-weight: 100;
  line-height: 1;
  background: linear-gradient(135deg, #764ba2 0%, #ec4899 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  will-change: transform, opacity;
}

.service-reveal-content {
  will-change: transform, opacity;
}

.service-reveal-name {
  font-size: clamp(1.8rem, 3vw, 2.5rem);
  font-weight: 100;
  color: rgba(255, 255, 255, 0.9);
  margin: 0 0 20px 0;
  letter-spacing: -0.02em;
}

.service-reveal-desc {
  font-size: clamp(0.9rem, 1.2vw, 1rem);
  font-weight: 100;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.4);
