  position: relative;
  z-index: 3;
  padding: 140px 80px 120px;
  background: transparent;
  overflow: hidden;
}

.why-modern-container {
  max-width: 1600px;
  margin: 0 auto;
  position: relative;
}

/* Sticky Side Label (Experimental Navigation) */
.side-label {
  position: absolute;
  left: -40px;
  top: 50%;
  transform: translateY(-50%) rotate(-90deg);
  transform-origin: center;
  z-index: 10;
}

.side-label-text {
  font-size: 11px;
  font-weight: 200;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.25);
  white-space: nowrap;
}

/* ==================== ASYMMETRIC GRID ==================== */

.why-modern-grid {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 80px;
  align-items: start;
}

/* ==================== LEFT: STATEMENT ==================== */

.why-statement {
  position: sticky;
  top: 120px;
  padding-right: 40px;
}

.why-statement-title {
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 100;
  line-height: 1.2;
  letter-spacing: -0.04em;
  margin: 0 0 30px 0;
  color: rgba(255, 255, 255, 0.95);
}

.statement-gradient {
  display: inline-block;
  background: linear-gradient(90deg, #667eea 0%, #764ba2 25%, #ec4899 50%, #f59e0b 75%, #667eea 100%);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: statementFlow 10s linear infinite;
}

@keyframes statementFlow {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

.why-statement-desc {
  font-size: clamp(1rem, 1.4vw, 1.15rem);
  font-weight: 200;
  line-height: 1.75;
  color: rgba(255, 255, 255, 0.5);
  margin: 0;
}

/* ==================== RIGHT: ADVANTAGE CARDS ==================== */

.why-advantages {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.advantage-card {
  display: grid;
  grid-template-columns: 60px 1fr;
  gap: 24px;
  padding: 0 0 24px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  position: relative;
  transition: all 0.4s ease;
}

.advantage-card:last-child {
  border-bottom: none;
}

/* Gradient line on hover */
.advantage-card::before {
  content: '';
  position: absolute;
  left: 0;
  bottom: -1px;
  width: 0;
  height: 1px;
  background: linear-gradient(90deg, #667eea, #ec4899);
  transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1);
}

.advantage-card:hover::before {
  width: 100%;
}

.card-number {
  font-size: 2.5rem;
  font-weight: 100;
  line-height: 1;
  color: rgba(255, 255, 255, 0.15);
  letter-spacing: -0.04em;
  transition: all 0.4s ease;
}

.advantage-card:hover .card-number {
  background: linear-gradient(135deg, #667eea, #ec4899);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  transform: scale(1.1);
}

.card-content {
  padding-top: 4px;
}

.card-title {
  font-size: clamp(1.2rem, 1.8vw, 1.5rem);
  font-weight: 200;
  color: rgba(255, 255, 255, 0.9);
  margin: 0 0 10px 0;
  letter-spacing: -0.02em;
  line-height: 1.3;
  transition: color 0.3s ease;
}

.advantage-card:hover .card-title {
  color: rgba(255, 255, 255, 1);
}

.card-desc {
  font-size: clamp(0.9rem, 1.1vw, 1rem);
  font-weight: 200;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.5);
  margin: 0;
  transition: color 0.3s ease;
}

.advantage-card:hover .card-desc {
  color: rgba(255, 255, 255, 0.65);
}

/* ==================== TRUST LINE ==================== */

.trust-modern {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 40px;
  margin-top: 80px;
  padding-top: 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.trust-item-modern {
  display: flex;
  flex-direction: column;
  gap: 4px;
  text-align: center;
}

.trust-label-modern {
  font-size: 10px;
  font-weight: 200;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.35);
}

.trust-value-modern {
  font-size: 13px;
  font-weight: 200;
  letter-spacing: 0.3px;
  color: rgba(255, 255, 255, 0.6);
}

.trust-divider-modern {
  width: 1px;
  height: 30px;
  background: rgba(255, 255, 255, 0.1);
}

/* ==================== RESPONSIVE ==================== */

@media (max-width: 1200px) {
  .why-modern-grid {
    grid-template-columns: 1fr;
    gap: 60px;
  }

  .why-statement {
    position: relative;
    top: 0;
    padding-right: 0;
    max-width: 700px;
  }

  .side-label {
    display: none;
  }
}

@media (max-width: 1024px) {
  .why-modern {
    padding: 100px 50px;
  }
}

@media (max-width: 768px) {
  .why-modern {
    padding: 90px 30px;
  }

  .advantage-card {
    grid-template-columns: 1fr;
    gap: 12px;
    padding-bottom: 20px;
  }

  .card-number {
    font-size: 2rem;
  }

  .trust-modern {
    flex-direction: column;
    gap: 24px;
  }

  .trust-divider-modern {
    width: 60px;
    height: 1px;
  }
}

@media (max-width: 480px) {
  .why-modern {
    padding: 80px 20px;
  }

  .why-statement-title {
    margin-bottom: 20px;
  }

  .trust-modern {
    margin-top: 60px;
    padding-top: 30px;
  }
}
/* ===================== PALETTE (REFERENCE) ===================== */
.proofB{
  --p1:#667eea !important;
  --p2:#764ba2 !important;
  --p3:#ec4899 !important;
  --p4:#f59e0b !important;

  --grad: linear-gradient(90deg, var(--p1) 0%, var(--p2) 25%, var(--p3) 55%, var(--p4) 85%, var(--p1) 100%) !important;
  --grad135: linear-gradient(135deg, var(--p1), var(--p3)) !important;

  --ink: rgba(255,255,255,.92) !important;
  --muted: rgba(255,255,255,.62) !important;

  position: relative !important;
  padding: 120px 80px !important;
  overflow: visible !important;
  background: transparent !important;
  z-index: 3 !important;
}

/* REMOVE BACKGROUND LAYERS COMPLETELY */
.proofB::before,
.proofB::after{
  content:none !important;
  display:none !important;
}

.proofB *{ box-sizing:border-box !important; font-family: inherit !important; }

.proofB__wrap{ max-width:1600px !important; margin:0 auto !important; position:relative !important; }

.proofB__eyebrow{
  margin:0 0 10px 0 !important;
  font-size:11px !important;
  font-weight:300 !important;
  letter-spacing:5px !important;
